import{c as r,Q as t,j as s,m as i}from"./chunks/framework.BPKcPtvA.js";const c=JSON.parse('{"title":"Server Requirements","description":"","frontmatter":{},"headers":[],"relativePath":"general/server-requirements.md","filePath":"general/server-requirements.md"}'),o={name:"general/server-requirements.md"};function a(n,e,l,d,h,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="server-requirements" tabindex="-1">Server Requirements <a class="header-anchor" href="#server-requirements" aria-label="Permalink to &quot;Server Requirements&quot;">​</a></h1><p>To avoid headaches with server-side issues, be sure to check our list of <a href="./recommended-web-hosts.html">Recommended Web Hosts</a>.</p><hr><p>To use our WordPress themes you must be running <strong>WordPress 6.0</strong> or higher, <strong>PHP 8.0</strong> or higher (PHP 8.3 recommended) and <strong>MySQL 7</strong> or higher. Our themes have been tested on all major browsers. Below is a checklist of items your host needs to comply with:</p><ul><li>Ensure your web host has the <a href="https://wordpress.org/about/requirements/" target="_blank" rel="noreferrer">recommended requirements</a> to run WordPress.</li><li>Make sure the <a href="https://wordpress.org/download/" target="_blank" rel="noreferrer">latest version of WordPress</a> is up and running.</li><li>If necessary, download the latest release from the official <a href="http://wordpress.org/" target="_blank" rel="noreferrer">WordPress</a> website.</li></ul><blockquote><p><strong>PHP note:</strong> Our themes work correctly with PHP 7.4+ however <strong>PHP 8.0 or higher is strongly recommended</strong>.</p></blockquote><h2 id="php-configuration-limits" tabindex="-1">PHP Configuration Limits <a class="header-anchor" href="#php-configuration-limits" aria-label="Permalink to &quot;PHP Configuration Limits&quot;">​</a></h2><p>Issues such as demo content failing to import are generally related to low PHP configuration limits. Ask your host to increase these to the following minimums:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Minimum</th></tr></thead><tbody><tr><td><code>memory_limit</code></td><td>256M</td></tr><tr><td><code>max_input_vars</code></td><td>3000</td></tr><tr><td><code>max_execution_time</code></td><td>300</td></tr><tr><td><code>post_max_size</code></td><td>256M</td></tr><tr><td><code>upload_max_filesize</code></td><td>256M</td></tr></tbody></table><p>If your host allows overriding PHP settings, create a <code>php.ini</code> file with the following and drop it in your <code>wp-admin</code> folder:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">memory_limit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 256M</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">max_input_vars</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 3000</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">max_execution_time</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 300</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">post_max_size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 256M</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">upload_max_filesize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 256M</span></span></code></pre></div><p>For <strong>Nginx</strong> based servers, use a <code>.user.ini</code> file instead following the same process.</p><h2 id="verify-your-server-limits" tabindex="-1">Verify Your Server Limits <a class="header-anchor" href="#verify-your-server-limits" aria-label="Permalink to &quot;Verify Your Server Limits&quot;">​</a></h2><p>Check your server limits via the System Status table or by installing the <a href="https://wordpress.org/plugins/wp-serverinfo/" target="_blank" rel="noreferrer">WP-ServerInfo</a> plugin and navigating to <strong>Settings &gt; WordPress phpinfo()</strong>.</p><p>Some hosts keep PHP limits low to conserve resources — you can always contact your host to have them adjusted.</p><hr><p><strong>Want to skip the hassle?</strong> <a href="https://wolfthemes.com/services/" target="_blank" rel="noreferrer">Explore our setup services</a></p>`,17)])])}const u=r(o,[["render",a]]);export{c as __pageData,u as default};
